    private lateinit var binding: ActivityCarritoBinding

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        binding = ActivityCarritoBinding.inflate(layoutInflater)
        setContentView(binding.root)
        configurarBarraNavegacion()

        // --- Recibir datos del plato desde el Intent ---
        val idPlato        = intent.getIntExtra("CARRITO_ID_PLATO", -1)
        val nombrePlato    = intent.getStringExtra("CARRITO_NOMBRE")    ?: ""
        val nombreTamano   = intent.getStringExtra("CARRITO_TAMANO")    ?: ""
        val cantidad       = intent.getIntExtra("CARRITO_CANTIDAD", 1)
        val precioUnitario = intent.getDoubleExtra("CARRITO_PRECIO_UNITARIO", 0.0)

        // --- Si no hay plato en el carrito, mostrar estado vacío ---
        if (idPlato == -1) {
            binding.cardPlato.visibility = android.view.View.GONE
            binding.layoutMetodoPago.visibility = android.view.View.GONE
            binding.tvCarritoTotal.visibility = android.view.View.GONE
            binding.btnIrAPagar.visibility = android.view.View.GONE
            binding.tvCarritoVacio.visibility = android.view.View.VISIBLE
            binding.btnCarritoAtras.setOnClickListener { finish() }
            return
        }

        var cantidadActual = cantidad
        val precioUnitarioActual = precioUnitario

        // --- Función local para actualizar toda la UI ---
        fun actualizarUI() {
            binding.tvCarritoCantidad.text = cantidadActual.toString()
            val precioTotalActual = precioUnitarioActual * cantidadActual
            val totalFormato = "$ %,.0f".format(precioTotalActual)
            binding.tvCarritoPrecioItem.text = totalFormato
            binding.tvCarritoTotal.text = getString(R.string.carrito_total, totalFormato)
            binding.btnIrAPagar.text = getString(R.string.carrito_ir_pagar, totalFormato)
        }

        // --- Datos iniciales ---
        binding.tvCarritoNombrePlato.text = nombrePlato.uppercase()
        binding.tvCarritoTamano.text      = nombreTamano.uppercase()
        actualizarUI()

        // --- Listeners de botones ---
        binding.btnCarritoMenos.setOnClickListener {
            if (cantidadActual > 1) {
                cantidadActual--
                actualizarUI()
            }
        }

        binding.btnCarritoMas.setOnClickListener {
            cantidadActual++
            actualizarUI()
        }

        binding.btnCarritoAtras.setOnClickListener { finish() }

        binding.btnIrAPagar.setOnClickListener {
            mostrarDialogoPedido(
                idPlato      = idPlato,
                nombrePlato  = nombrePlato,
                nombreTamano = nombreTamano,
                cantidad     = cantidadActual,
                precio       = precioUnitarioActual
            )
        }
    }

    /**
     * Diálogo de tipo de pedido: Reservar en restaurante vs. Domicilio.
     * Principio SRP: Encapsula la lógica del diálogo en su propio método.
     */
    private fun mostrarDialogoPedido(
        idPlato: Int, nombrePlato: String, nombreTamano: String,
        cantidad: Int, precio: Double
    ) {
        val dialogView = layoutInflater.inflate(R.layout.dialog_tipo_pedido, null)
        val dialog = AlertDialog.Builder(this, R.style.DialogTamano)
            .setView(dialogView)
            .create()

        // Opción: Reservar en restaurante → Navegar a datos del cliente
        dialogView.findViewById<Button>(R.id.btnReservarRestaurante).setOnClickListener {
            dialog.dismiss()
            val intent = Intent(this, DatosClienteActivity::class.java).apply {
                putExtra("CARRITO_ID_PLATO",        idPlato)
                putExtra("CARRITO_NOMBRE",          nombrePlato)
                putExtra("CARRITO_TAMANO",          nombreTamano)
                putExtra("CARRITO_CANTIDAD",        cantidad)
                putExtra("CARRITO_PRECIO_UNITARIO", precio)
            }
            startActivity(intent)
        }

        // Opción: Domicilio → Navegar a datos del cliente con flag domicilio
        dialogView.findViewById<Button>(R.id.btnDomicilio).setOnClickListener {
            dialog.dismiss()
            val intent = Intent(this, DatosClienteActivity::class.java).apply {
                putExtra("CARRITO_ID_PLATO",        idPlato)
                putExtra("CARRITO_NOMBRE",          nombrePlato)
                putExtra("CARRITO_TAMANO",          nombreTamano)
                putExtra("CARRITO_CANTIDAD",        cantidad)
                putExtra("CARRITO_PRECIO_UNITARIO", precio)
                putExtra("FLUJO_DOMICILIO",         true)
            }
            startActivity(intent)
        }

        dialogView.findViewById<TextView>(R.id.btnCancelar).setOnClickListener {
            dialog.dismiss()
        }

        dialog.show()
    }
}

package com.sena.myapplication.views

import android.content.Intent
import android.graphics.BitmapFactory
import android.os.Bundle
import android.util.Base64
import com.sena.myapplication.databinding.ActivityConfirmacionReservaBinding

/**
 * Pantalla de confirmación — Muestra el código QR de la reserva creada.
 *
 * Recibe el QR en formato Base64 vía Intent extra "QR_BASE64".
 * El botón "Finalizar" limpia la pila de Activities y vuelve al inicio.
 *
 * Nota: Esta Activity extiende BaseActivity para mantener consistencia
 * con la barra de navegación, aunque el flujo normalmente termina aquí.
 */
class ConfirmacionReservaActivity : BaseActivity() {

    private lateinit var binding: ActivityConfirmacionReservaBinding

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        binding = ActivityConfirmacionReservaBinding.inflate(layoutInflater)
        setContentView(binding.root)
        configurarBarraNavegacion()

        // --- Decodificar y mostrar el QR en Base64 ---
        val qrBase64 = intent.getStringExtra("QR_BASE64") ?: ""

        if (qrBase64.isNotEmpty()) {
            try {
                val bytes  = Base64.decode(qrBase64, Base64.DEFAULT)
                val bitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
                binding.imgQr.setImageBitmap(bitmap)
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }

        // --- Botón Finalizar: Volver al inicio limpiando toda la pila ---
        binding.btnFinalizar.setOnClickListener {
            val intent = Intent(this, MainActivity::class.java)
            intent.flags = Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_NEW_TASK
            startActivity(intent)
            finish()
        }
    }
}

package com.sena.myapplication.views

import android.content.ContentValues
import android.content.Intent
import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.os.Build
import android.os.Bundle
import android.os.Environment
import android.provider.MediaStore
import android.util.Base64
import android.widget.Toast
import com.sena.myapplication.databinding.ActivityConfirmacionReservaBinding
import java.io.File
import java.io.FileOutputStream

/**
 * Pantalla de confirmación — Muestra el código QR de la reserva/domicilio.
 *
 * Recibe el QR en formato Base64 vía Intent extra "QR_BASE64".
 * Permite descargar el QR a la galería del dispositivo.
 * El botón "Finalizar" limpia la pila de Activities y vuelve al inicio.
 */
class ConfirmacionReservaActivity : BaseActivity() {

    private lateinit var binding: ActivityConfirmacionReservaBinding
    private var qrBitmap: Bitmap? = null

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        binding = ActivityConfirmacionReservaBinding.inflate(layoutInflater)
        setContentView(binding.root)
        configurarBarraNavegacion()

        // --- Decodificar y mostrar el QR en Base64 ---
        val qrBase64 = intent.getStringExtra("QR_BASE64") ?: ""

        if (qrBase64.isNotEmpty()) {
            try {
                val bytes = Base64.decode(qrBase64, Base64.DEFAULT)
                qrBitmap = BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
                binding.imgQr.setImageBitmap(qrBitmap)
            } catch (e: Exception) {
                e.printStackTrace()
            }
        }

        // --- Botón Descargar QR ---
        binding.btnDescargarQr.setOnClickListener {
            guardarQrEnGaleria()
        }

        // --- Botón Finalizar: Volver al inicio limpiando toda la pila ---
        binding.btnFinalizar.setOnClickListener {
            val intent = Intent(this, MainActivity::class.java)
            intent.flags = Intent.FLAG_ACTIVITY_CLEAR_TOP or Intent.FLAG_ACTIVITY_NEW_TASK
            startActivity(intent)
            finish()
        }
    }

    /**
     * Guarda el QR como imagen PNG en la galería del dispositivo.
     *
     * Para API 29+ (Android 10+): Usa MediaStore (no requiere permisos).
     * Para API < 29: Escribe directamente en la carpeta Pictures.
     */
    private fun guardarQrEnGaleria() {
        val bitmap = qrBitmap
        if (bitmap == null) {
            Toast.makeText(this, "No hay código QR para descargar", Toast.LENGTH_SHORT).show()
            return
        }

        try {
            val nombreArchivo = "QR_Pedido_${System.currentTimeMillis()}.png"

            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
                // Android 10+ → MediaStore (sin permisos)
                val contentValues = ContentValues().apply {
                    put(MediaStore.Images.Media.DISPLAY_NAME, nombreArchivo)
                    put(MediaStore.Images.Media.MIME_TYPE, "image/png")
                    put(MediaStore.Images.Media.RELATIVE_PATH, Environment.DIRECTORY_PICTURES + "/SaboresUnidos")
                    put(MediaStore.Images.Media.IS_PENDING, 1)
                }

                val uri = contentResolver.insert(
                    MediaStore.Images.Media.EXTERNAL_CONTENT_URI, contentValues
                )

                uri?.let {
                    contentResolver.openOutputStream(it)?.use { outputStream ->
                        bitmap.compress(Bitmap.CompressFormat.PNG, 100, outputStream)
                    }
                    contentValues.clear()
                    contentValues.put(MediaStore.Images.Media.IS_PENDING, 0)
                    contentResolver.update(it, contentValues, null, null)

                    Toast.makeText(this, "QR guardado en Galería/SaboresUnidos", Toast.LENGTH_LONG).show()
                } ?: run {
                    Toast.makeText(this, "Error al guardar el QR", Toast.LENGTH_SHORT).show()
                }
            } else {
                // Android 9 y anteriores → Escritura directa
                val directorio = File(
                    Environment.getExternalStoragePublicDirectory(Environment.DIRECTORY_PICTURES),
                    "SaboresUnidos"
                )
                if (!directorio.exists()) directorio.mkdirs()

                val archivo = File(directorio, nombreArchivo)
                FileOutputStream(archivo).use { outputStream ->
                    bitmap.compress(Bitmap.CompressFormat.PNG, 100, outputStream)
                }

                // Notificar a la galería
                val mediaScanIntent = Intent(Intent.ACTION_MEDIA_SCANNER_SCAN_FILE)
                mediaScanIntent.data = android.net.Uri.fromFile(archivo)
                sendBroadcast(mediaScanIntent)

                Toast.makeText(this, "QR guardado en Pictures/SaboresUnidos", Toast.LENGTH_LONG).show()
            }
        } catch (e: Exception) {
            e.printStackTrace()
            Toast.makeText(this, "Error al descargar: ${e.message}", Toast.LENGTH_LONG).show()
        }
    }
}

package com.sena.myapplication.views

import android.content.Intent
import android.os.Bundle
import android.widget.Toast
import com.sena.myapplication.databinding.ActivityDatosClienteBinding

/**
 * Pantalla de datos del cliente — Formulario para recopilar nombre,
 * cédula, correo y teléfono antes de continuar con la reserva o domicilio.
 *
 * Recibe datos del carrito (prefijo CARRITO_*) y un flag FLUJO_DOMICILIO
 * que determina si el siguiente paso es ReservaActivity o DomicilioActivity.
 *
 * Implementa validaciones de campos vacíos, formato de correo
 * y aceptación obligatoria del checkbox de Habeas Data.
 */
class DatosClienteActivity : BaseActivity() {

    private lateinit var binding: ActivityDatosClienteBinding

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        binding = ActivityDatosClienteBinding.inflate(layoutInflater)
        setContentView(binding.root)
        configurarBarraNavegacion()

        // --- Recibir extras del carrito ---
        val carritoIdPlato  = intent.getIntExtra("CARRITO_ID_PLATO", -1)
        val carritoNombre   = intent.getStringExtra("CARRITO_NOMBRE") ?: ""
        val carritoTamano   = intent.getStringExtra("CARRITO_TAMANO") ?: ""
        val carritoCantidad = intent.getIntExtra("CARRITO_CANTIDAD", 1)
        val carritoPrecio   = intent.getDoubleExtra("CARRITO_PRECIO_UNITARIO", 0.0)

        // Flag que indica si el flujo es domicilio (true) o restaurante (false)
        val esDomicilio = intent.getBooleanExtra("FLUJO_DOMICILIO", false)

        // --- Listeners ---
        binding.btnVolver.setOnClickListener { finish() }

        binding.btnContinuar.setOnClickListener {
            // Extraer y limpiar valores del formulario
            val nombre   = binding.etNombre.text.toString().trim()
            val cedula   = binding.etCedula.text.toString().trim()
            val correo   = binding.etCorreo.text.toString().trim()
            val telefono = binding.etTelefono.text.toString().trim()

            // --- Validaciones de campos vacíos ---
            if (!validarCamposObligatorios(nombre, cedula, correo, telefono)) return@setOnClickListener

            // --- Validación de formato de correo ---
            if (!android.util.Patterns.EMAIL_ADDRESS.matcher(correo).matches()) {
                Toast.makeText(this, "Correo no válido", Toast.LENGTH_SHORT).show()
                return@setOnClickListener
            }

            // --- Validación de Habeas Data ---
            if (!binding.cbHabeasData.isChecked) {
                Toast.makeText(this, "Debes aceptar la política de tratamiento de datos", Toast.LENGTH_SHORT).show()
                return@setOnClickListener
            }

            // Determinar destino según el flujo
            val destino = if (esDomicilio) DomicilioActivity::class.java
                          else ReservaActivity::class.java

            val intent = Intent(this, destino).apply {
                // Datos del cliente
                putExtra("CLI_NOMBRE",   nombre)
                putExtra("CLI_CEDULA",   cedula)
                putExtra("CLI_CORREO",   correo)
                putExtra("CLI_TELEFONO", telefono)
                // Datos del carrito (se propagan para armar el pedido)
                putExtra("CARRITO_ID_PLATO",        carritoIdPlato)
                putExtra("CARRITO_NOMBRE",          carritoNombre)
                putExtra("CARRITO_TAMANO",          carritoTamano)
                putExtra("CARRITO_CANTIDAD",        carritoCantidad)
                putExtra("CARRITO_PRECIO_UNITARIO", carritoPrecio)
            }
            startActivity(intent)
        }
    }

    /**
     * Valida todos los campos del formulario de datos del cliente.
     * Verifica campos vacíos, longitud mínima/máxima y formatos.
     *
     * @return true si todo es válido, false si hay algún error.
     */
    private fun validarCamposObligatorios(
        nombre: String, cedula: String, correo: String, telefono: String
    ): Boolean {
        // --- Nombre: 3–50 caracteres, solo letras y espacios ---
        if (nombre.isEmpty()) {
            Toast.makeText(this, "Ingresa tu nombre", Toast.LENGTH_SHORT).show()
            return false
        }
        if (nombre.length < 3) {
            Toast.makeText(this, "El nombre debe tener al menos 3 caracteres", Toast.LENGTH_SHORT).show()
            return false
        }

        // --- Cédula: 6–10 dígitos numéricos ---
        if (cedula.isEmpty()) {
            Toast.makeText(this, "Ingresa tu cédula", Toast.LENGTH_SHORT).show()
            return false
        }
        if (cedula.length < 6) {
            Toast.makeText(this, "La cédula debe tener al menos 6 dígitos", Toast.LENGTH_SHORT).show()
            return false
        }

        // --- Correo: no vacío (formato se valida aparte) ---
        if (correo.isEmpty()) {
            Toast.makeText(this, "Ingresa tu correo", Toast.LENGTH_SHORT).show()
            return false
        }

        // --- Teléfono: exactamente 10 dígitos ---
        if (telefono.isEmpty()) {
            Toast.makeText(this, "Ingresa tu teléfono", Toast.LENGTH_SHORT).show()
            return false
        }
        if (telefono.length != 10) {
            Toast.makeText(this, "El teléfono debe tener 10 dígitos", Toast.LENGTH_SHORT).show()
            return false
        }

        return true
    }
}

package com.sena.myapplication.views

import android.content.Intent
import android.os.Bundle
import android.widget.Toast
import com.sena.myapplication.databinding.ActivityDatosClienteBinding

/**
 * Pantalla de datos del cliente — Formulario para recopilar nombre,
 * cédula, correo y teléfono antes de continuar con la reserva o domicilio.
 *
 * Principio SRP: Solo gestiona la recopilación y validación de datos
 * del cliente. No realiza llamadas de red.
 *
 * Principio OCP: Hereda la barra de navegación de [BaseActivity].
 * Las validaciones se encapsulan en [validarCamposObligatorios] para
 * facilitar su extensión sin modificar el flujo principal.
 *
 * Recibe datos del carrito (prefijo CARRITO_*) y un flag FLUJO_DOMICILIO
 * que determina si el siguiente paso es ReservaActivity o DomicilioActivity.
 *
 * Implementa validaciones de campos vacíos, formato numérico,
 * formato de correo y aceptación obligatoria del checkbox de Habeas Data.
 */
class DatosClienteActivity : BaseActivity() {

    private lateinit var binding: ActivityDatosClienteBinding

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        binding = ActivityDatosClienteBinding.inflate(layoutInflater)
        setContentView(binding.root)
        configurarBarraNavegacion()

        // --- Recibir extras del carrito ---
        val carritoIdPlato  = intent.getIntExtra("CARRITO_ID_PLATO", -1)
        val carritoNombre   = intent.getStringExtra("CARRITO_NOMBRE") ?: ""
        val carritoTamano   = intent.getStringExtra("CARRITO_TAMANO") ?: ""
        val carritoCantidad = intent.getIntExtra("CARRITO_CANTIDAD", 1)
        val carritoPrecio   = intent.getDoubleExtra("CARRITO_PRECIO_UNITARIO", 0.0)

        // Flag que indica si el flujo es domicilio (true) o restaurante (false)
        val esDomicilio = intent.getBooleanExtra("FLUJO_DOMICILIO", false)

        // --- Listeners ---
        binding.btnVolver.setOnClickListener { finish() }

        binding.btnContinuar.setOnClickListener {
            // Extraer y limpiar valores del formulario
            val nombre   = binding.etNombre.text.toString().trim()
            val cedula   = binding.etCedula.text.toString().trim()
            val correo   = binding.etCorreo.text.toString().trim()
            val telefono = binding.etTelefono.text.toString().trim()

            // --- Validaciones de campos vacíos ---
            if (!validarCamposObligatorios(nombre, cedula, correo, telefono)) return@setOnClickListener

            // --- Validación de formato de correo ---
            if (!android.util.Patterns.EMAIL_ADDRESS.matcher(correo).matches()) {
                Toast.makeText(this, "Correo no válido", Toast.LENGTH_SHORT).show()
                return@setOnClickListener
            }

            // --- Validación de Habeas Data ---
            if (!binding.cbHabeasData.isChecked) {
                Toast.makeText(this, "Debes aceptar la política de tratamiento de datos", Toast.LENGTH_SHORT).show()
                return@setOnClickListener
            }

            // Determinar destino según el flujo
            val destino = if (esDomicilio) DomicilioActivity::class.java
                          else ReservaActivity::class.java

            val intent = Intent(this, destino).apply {
                // Datos del cliente
                putExtra("CLI_NOMBRE",   nombre)
                putExtra("CLI_CEDULA",   cedula)
                putExtra("CLI_CORREO",   correo)
                putExtra("CLI_TELEFONO", telefono)
                // Datos del carrito (se propagan para armar el pedido)
                putExtra("CARRITO_ID_PLATO",        carritoIdPlato)
                putExtra("CARRITO_NOMBRE",          carritoNombre)
                putExtra("CARRITO_TAMANO",          carritoTamano)
                putExtra("CARRITO_CANTIDAD",        carritoCantidad)
                putExtra("CARRITO_PRECIO_UNITARIO", carritoPrecio)
            }
            startActivity(intent)
        }
    }

    /**
     * Valida todos los campos del formulario de datos del cliente.
     * Verifica campos vacíos, longitud mínima/máxima y formatos.
     *
     * @return true si todo es válido, false si hay algún error.
     */
    private fun validarCamposObligatorios(
        nombre: String, cedula: String, correo: String, telefono: String
    ): Boolean {
        // --- Nombre: 3–50 caracteres, solo letras y espacios ---
        if (nombre.isEmpty()) {
            Toast.makeText(this, "Ingresa tu nombre", Toast.LENGTH_SHORT).show()
            return false
        }
        if (nombre.length < 3) {
            Toast.makeText(this, "El nombre debe tener al menos 3 caracteres", Toast.LENGTH_SHORT).show()
            return false
        }

        // --- Cédula: 6–10 dígitos numéricos ---
        if (cedula.isEmpty()) {
            Toast.makeText(this, "Ingresa tu cédula", Toast.LENGTH_SHORT).show()
            return false
        }
        if (cedula.length < 6) {
            Toast.makeText(this, "La cédula debe tener al menos 6 dígitos", Toast.LENGTH_SHORT).show()
            return false
        }

        // --- Correo: no vacío (formato se valida aparte) ---
        if (correo.isEmpty()) {
            Toast.makeText(this, "Ingresa tu correo", Toast.LENGTH_SHORT).show()
            return false
        }

        // --- Teléfono: exactamente 10 dígitos ---
        if (telefono.isEmpty()) {
            Toast.makeText(this, "Ingresa tu teléfono", Toast.LENGTH_SHORT).show()
            return false
        }
        if (telefono.length != 10) {
            Toast.makeText(this, "El teléfono debe tener 10 dígitos", Toast.LENGTH_SHORT).show()
            return false
        }

        return true
    }
}

package com.sena.myapplication.views

import android.app.Dialog
import android.content.Intent
import android.graphics.Color
import android.graphics.drawable.ColorDrawable
import android.net.Uri
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.Window
import android.widget.Button
import android.widget.ImageButton
import android.widget.LinearLayout
import android.widget.TextView
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.lifecycle.ViewModelProvider
import com.sena.myapplication.R
import com.sena.myapplication.databinding.ActivityDomicilioBinding
import com.sena.myapplication.models.ClienteReserva
import com.sena.myapplication.models.DatosDomicilio
import com.sena.myapplication.models.DomicilioRequest
import com.sena.myapplication.models.PedidoItem
import com.sena.myapplication.viewmodels.ViewModelDomicilio
import java.text.NumberFormat
import java.util.Locale

/**
 * Pantalla de envío a domicilio — Recopila dirección, barrio/referencia
 * y método de pago para completar el pedido.
 *
 * Recibe datos del cliente (CLI_*) y del carrito (CARRITO_*) vía Intent extras.
 * Al confirmar, envía el pedido vía [ViewModelDomicilio] a POST /api/domicilios.
 *
 * Patrón MVVM: La Activity solo gestiona la UI; la lógica de red
 * se delega al ViewModel.
 */
class DomicilioActivity : BaseActivity() {

    private lateinit var binding: ActivityDomicilioBinding
    private lateinit var viewModel: ViewModelDomicilio

    // Estado del selector de método de pago
    private val opcionesMetodoPago = listOf("Efectivo (Contra entrega)", "Transferencia")
    private var metodoPagoPos: Int = 0
    private var metodoPagoStr: String = "efectivo"

    // Estado para el comprobante de transferencia
    private var comprobanteUri: Uri? = null
    private var dialogTransferenciaActivo: Dialog? = null

    /** Launcher para seleccionar imagen del comprobante desde la galería */
    private val selectorComprobante = registerForActivityResult(
        ActivityResultContracts.GetContent()
    ) { uri: Uri? ->
        uri?.let {
            comprobanteUri = it
            dialogTransferenciaActivo?.findViewById<TextView>(R.id.tvNombreArchivo)?.text =
                obtenerNombreArchivo(it)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        binding = ActivityDomicilioBinding.inflate(layoutInflater)
        setContentView(binding.root)
        configurarBarraNavegacion()

        // --- Recibir datos del Intent ---
        val cliNombre   = intent.getStringExtra("CLI_NOMBRE") ?: ""
        val cliCedula   = intent.getStringExtra("CLI_CEDULA") ?: ""
        val cliCorreo   = intent.getStringExtra("CLI_CORREO") ?: ""
        val cliTelefono = intent.getStringExtra("CLI_TELEFONO") ?: ""

        val carritoIdPlato  = intent.getIntExtra("CARRITO_ID_PLATO", -1)
        val carritoCantidad = intent.getIntExtra("CARRITO_CANTIDAD", 1)
        val carritoPrecio   = intent.getDoubleExtra("CARRITO_PRECIO_UNITARIO", 0.0)

        // --- Inicializar ViewModel ---
        viewModel = ViewModelProvider(this)[ViewModelDomicilio::class.java]

        // Observar resultado exitoso → navegar a confirmación
        viewModel.pedidoExitoso.observe(this) { response ->
            response?.let {
                val intent = Intent(this, ConfirmacionReservaActivity::class.java)
                intent.putExtra("QR_BASE64", it.qr ?: "")
                startActivity(intent)
                finishAffinity()
            }
        }

        // Observar errores
        viewModel.error.observe(this) { mensajeError ->
            mensajeError?.let {
                Toast.makeText(this, it, Toast.LENGTH_LONG).show()
            }
        }

        // Observar estado de envío para habilitar/deshabilitar botón
        viewModel.enviando.observe(this) { enviando ->
            binding.btnConfirmarPedido.isEnabled = !enviando
            binding.btnConfirmarPedido.text = if (enviando) "Enviando..." else "CONFIRMAR PEDIDO"
        }

        // --- Listeners ---
        binding.btnVolverDomicilio.setOnClickListener { finish() }

        // Selector de método de pago con diálogo personalizado
        binding.btnMetodoPago.setOnClickListener {
            mostrarDialogoSelector("Método de Pago", opcionesMetodoPago, metodoPagoPos) { pos, texto ->
                metodoPagoPos = pos
                metodoPagoStr = when {
                    texto.contains("Efectivo", ignoreCase = true) -> "efectivo"
                    texto.contains("Transferencia", ignoreCase = true) -> "transferencia"
                    else -> texto.lowercase()
                }
                binding.btnMetodoPago.text = texto
            }
        }

        binding.btnConfirmarPedido.setOnClickListener {
            val direccion = binding.etDireccion.text.toString().trim()
            val barrio    = binding.etBarrio.text.toString().trim()

            // Validaciones
            if (!validarFormularioEnvio(direccion, barrio)) return@setOnClickListener

            // Concatenar dirección + barrio en un solo campo (el backend solo almacena "direccion")
            val direccionCompleta = "$direccion - $barrio"

            // Construir el body del request (claves: cliente, domicilio, productos)
            val body = DomicilioRequest(
                cliente = ClienteReserva(
                    doc = cliCedula,
                    nom = cliNombre,
                    correo = cliCorreo,
                    tel = cliTelefono
                ),
                domicilio = DatosDomicilio(
                    direccion = direccionCompleta,
                    metodoPago = metodoPagoStr
                ),
                productos = if (carritoIdPlato != -1) listOf(
                    PedidoItem(
                        id = carritoIdPlato,
                        cantidad = carritoCantidad,
                        precio = carritoPrecio
                    )
                ) else emptyList()
            )

            // Si es transferencia, mostrar diálogo con datos bancarios
            if (metodoPagoStr == "transferencia") {
                val total = carritoPrecio * carritoCantidad
                mostrarDialogoTransferencia(total) {
                    viewModel.crearDomicilio(body)
                }
            } else {
                // Efectivo: enviar directo
                viewModel.crearDomicilio(body)
            }
        }
    }

    // ==================== VALIDACIONES ====================

    /**
     * Valida que los campos obligatorios del formulario de envío estén completos.
     *
     * @return true si todo es válido, false si falta algún campo.
     */
    private fun validarFormularioEnvio(direccion: String, barrio: String): Boolean {
        if (direccion.isEmpty()) {
            Toast.makeText(this, "Ingresa la dirección completa", Toast.LENGTH_SHORT).show()
            return false
        }
        if (direccion.length < 5) {
            Toast.makeText(this, "La dirección debe tener al menos 5 caracteres", Toast.LENGTH_SHORT).show()
            return false
        }
        if (barrio.isEmpty()) {
            Toast.makeText(this, "Ingresa el barrio o referencia", Toast.LENGTH_SHORT).show()
            return false
        }
        if (barrio.length < 3) {
            Toast.makeText(this, "El barrio debe tener al menos 3 caracteres", Toast.LENGTH_SHORT).show()
            return false
        }
        return true
    }

    // ==================== DIÁLOGO SELECTOR GENÉRICO ====================

    /**
     * Muestra un diálogo personalizado con opciones seleccionables.
     * Reutiliza el mismo layout [R.layout.dialog_selector_generico]
     * que usa [ReservaActivity].
     *
     * Principio DRY: Misma lógica de selector visual.
     */
    private fun mostrarDialogoSelector(
        titulo: String,
        opciones: List<String>,
        indiceActual: Int,
        alSeleccionar: (Int, String) -> Unit
    ) {
        val dialog = Dialog(this)
        dialog.requestWindowFeature(Window.FEATURE_NO_TITLE)
        dialog.setContentView(R.layout.dialog_selector_generico)
        dialog.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))

        dialog.findViewById<TextView>(R.id.tvTituloDialogo).text = titulo
        val contenedor = dialog.findViewById<LinearLayout>(R.id.contenedorOpciones)

        var indiceTemp = if (indiceActual == -1 && opciones.isNotEmpty()) 0 else indiceActual
        val vistasFilas = mutableListOf<View>()

        for (i in opciones.indices) {
            val vistaFila = LayoutInflater.from(this)
                .inflate(R.layout.item_opcion_dialogo, contenedor, false)
            val tvTexto  = vistaFila.findViewById<TextView>(R.id.tvTextoOpcion)
            val imgCheck = vistaFila.findViewById<ImageButton>(R.id.imgCheckOpcion)

            tvTexto.text = opciones[i]

            if (i == indiceTemp) {
                imgCheck.setImageResource(R.drawable.ic_radio_seleccionado)
                tvTexto.setTextColor(Color.parseColor("#FFFFFF"))
            } else {
                imgCheck.setImageResource(R.drawable.ic_radio_vacio)
                tvTexto.setTextColor(Color.parseColor("#99FFFFFF"))
            }

            vistaFila.setOnClickListener {
                indiceTemp = i
                vistasFilas.forEachIndexed { index, vista ->
                    val img = vista.findViewById<ImageButton>(R.id.imgCheckOpcion)
                    val txt = vista.findViewById<TextView>(R.id.tvTextoOpcion)

                    if (index == indiceTemp) {
                        img.setImageResource(R.drawable.ic_radio_seleccionado)
                        txt.setTextColor(Color.parseColor("#FFFFFF"))
                    } else {
                        img.setImageResource(R.drawable.ic_radio_vacio)
                        txt.setTextColor(Color.parseColor("#99FFFFFF"))
                    }
                }
            }

            contenedor.addView(vistaFila)
            vistasFilas.add(vistaFila)
        }

        dialog.findViewById<Button>(R.id.btnCancelarDialogo).setOnClickListener { dialog.dismiss() }
        dialog.findViewById<Button>(R.id.btnAceptarDialogo).setOnClickListener {
            if (indiceTemp != -1) alSeleccionar(indiceTemp, opciones[indiceTemp])
            dialog.dismiss()
        }
        dialog.show()
    }

    // ==================== DIÁLOGO TRANSFERENCIA ====================

    /**
     * Muestra un diálogo con los datos bancarios para transferencia,
     * similar a la versión web del restaurante.
     *
     * @param total Monto total a pagar.
     * @param alConfirmar Lambda que se ejecuta al confirmar el envío del comprobante.
     */
    private fun mostrarDialogoTransferencia(total: Double, alConfirmar: () -> Unit) {
        comprobanteUri = null

        val dialog = Dialog(this)
        dialog.requestWindowFeature(Window.FEATURE_NO_TITLE)
        dialog.setContentView(R.layout.dialog_transferencia)
        dialog.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
        dialogTransferenciaActivo = dialog

        val formato = NumberFormat.getNumberInstance(Locale("es", "CO"))
        formato.maximumFractionDigits = 0
        val totalFormateado = formato.format(total)

        dialog.findViewById<TextView>(R.id.tvTotalPagar).text = "TOTAL A PAGAR: $ $totalFormateado"

        dialog.findViewById<LinearLayout>(R.id.layoutSeleccionarComprobante).setOnClickListener {
            selectorComprobante.launch("image/*")
        }

        dialog.findViewById<Button>(R.id.btnEnviarComprobante).setOnClickListener {
            if (comprobanteUri == null) {
                Toast.makeText(this, "Selecciona un comprobante de pago", Toast.LENGTH_SHORT).show()
                return@setOnClickListener
            }
            dialog.dismiss()
            dialogTransferenciaActivo = null
            alConfirmar()
        }

        dialog.findViewById<Button>(R.id.btnCancelarTransferencia).setOnClickListener {
            dialog.dismiss()
            dialogTransferenciaActivo = null
        }

        dialog.setOnDismissListener { dialogTransferenciaActivo = null }
        dialog.show()
    }

    /**
     * Obtiene el nombre del archivo desde una URI de contenido.
     */
    private fun obtenerNombreArchivo(uri: Uri): String {
        var nombre = "Comprobante seleccionado"
        contentResolver.query(uri, null, null, null, null)?.use { cursor ->
            val index = cursor.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
            if (index != -1 && cursor.moveToFirst()) {
                nombre = cursor.getString(index)
            }
        }
        return nombre
    }
}

