package com.sena.myapplication.views

import android.app.DatePickerDialog
import android.app.Dialog
import android.content.Intent
import android.graphics.Color
import android.graphics.drawable.ColorDrawable
import android.net.Uri
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.Window
import android.widget.Button
import android.widget.ImageButton
import android.widget.LinearLayout
import android.widget.TextView
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.lifecycle.ViewModelProvider
import com.sena.myapplication.R
import com.sena.myapplication.databinding.ActivityReservaBinding
import com.sena.myapplication.models.*
import com.sena.myapplication.viewmodels.ViewModelReserva
import java.text.NumberFormat
import java.util.Calendar
import java.util.Locale

/**
 * Pantalla de reserva — El usuario selecciona fecha, hora, temática,
 * piso, método de pago y número de personas.
 *
 * Patrón MVVM: Toda la lógica de red (cargar temáticas, enviar reserva)
 * se delega a [ViewModelReserva]. La Activity solo gestiona la UI.
 *
 * Recibe datos del cliente (CLI_*) y del carrito (CARRITO_*) para
 * construir el [ReservaRequest] completo.
 */
class ReservaActivity : BaseActivity() {

    private lateinit var binding: ActivityReservaBinding
    private lateinit var viewModel: ViewModelReserva

    // Estado de selección de la reserva
    private var listaTematicas: List<ModelTematica> = emptyList()
    private var fechaSeleccionada = ""
    private var bloqueHoraStr = ""
    private var bloquePos = -1
    private var tematicaSeleccionadaId = -1
    private var tematicaPos = -1
    private var pisoNumInt = -1
    private var pisoPos = -1
    private var metodoPagoStr = ""
    private var metodoPos = -1

    // Estado para el comprobante de transferencia
    private var comprobanteUri: Uri? = null
    private var dialogTransferenciaActivo: Dialog? = null

    /** Launcher para seleccionar imagen del comprobante desde la galería */
    private val selectorComprobante = registerForActivityResult(
        ActivityResultContracts.GetContent()
    ) { uri: Uri? ->
        uri?.let {
            comprobanteUri = it
            // Actualizar texto en el diálogo activo
            dialogTransferenciaActivo?.findViewById<TextView>(R.id.tvNombreArchivo)?.text =
                obtenerNombreArchivo(it)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        binding = ActivityReservaBinding.inflate(layoutInflater)
        setContentView(binding.root)
        configurarBarraNavegacion()

        // --- Recibir datos del Intent ---
        val cliNombre   = intent.getStringExtra("CLI_NOMBRE") ?: ""
        val cliCedula   = intent.getStringExtra("CLI_CEDULA") ?: ""
        val cliCorreo   = intent.getStringExtra("CLI_CORREO") ?: ""
        val cliTelefono = intent.getStringExtra("CLI_TELEFONO") ?: ""

        val carritoIdPlato  = intent.getIntExtra("CARRITO_ID_PLATO", -1)
        val carritoCantidad = intent.getIntExtra("CARRITO_CANTIDAD", 1)
        val carritoPrecio   = intent.getDoubleExtra("CARRITO_PRECIO_UNITARIO", 0.0)

        // --- Opciones de selección ---
        val opcionesBloque = (6..22).map { "$it:00" }
        val opcionesPiso   = listOf("Piso 1", "Piso 2")
        val opcionesMetodo = listOf("Efectivo", "Transferencia")

        // --- Inicializar ViewModel ---
        viewModel = ViewModelProvider(this)[ViewModelReserva::class.java]

        // Observar temáticas cargadas
        viewModel.tematicas.observe(this) { tematicas ->
            listaTematicas = tematicas
            binding.btnTematica.text = "Seleccionar Temática"
            binding.btnTematica.isEnabled = true
        }

        // Observar resultado de crear reserva → navegar a confirmación
        viewModel.reservaExitosa.observe(this) { response ->
            response?.let {
                val intent = Intent(this, ConfirmacionReservaActivity::class.java)
                intent.putExtra("QR_BASE64", it.qr ?: "")
                startActivity(intent)
                finishAffinity()
            }
        }

        // Observar errores de red
        viewModel.error.observe(this) { mensajeError ->
            mensajeError?.let {
                Toast.makeText(this, it, Toast.LENGTH_LONG).show()
            }
        }

        // Observar estado de envío para habilitar/deshabilitar botón
        viewModel.enviando.observe(this) { enviando ->
            binding.btnReservar.isEnabled = !enviando
            binding.btnReservar.text = if (enviando) "Enviando..." else "RESERVAR"
        }

        // Disparar carga de temáticas
        viewModel.cargarTematicas()

        // --- Listeners de selección ---

        binding.btnFecha.setOnClickListener {
            val manana = Calendar.getInstance()
            manana.add(Calendar.DAY_OF_YEAR, 1)

            val picker = DatePickerDialog(
                this, R.style.CalendarioPersonalizado, { _, y, m, d ->
                    val mes = String.format("%02d", m + 1)
                    val dia = String.format("%02d", d)
                    fechaSeleccionada = "$y-$mes-$dia"
                    binding.btnFecha.text = fechaSeleccionada
                }, manana.get(Calendar.YEAR), manana.get(Calendar.MONTH), manana.get(Calendar.DAY_OF_MONTH)
            )
            picker.datePicker.minDate = manana.timeInMillis
            picker.show()
        }

        binding.btnBloque.setOnClickListener {
            mostrarDialogoSelector("Bloque Horario", opcionesBloque, bloquePos) { pos, texto ->
                bloquePos = pos
                bloqueHoraStr = texto.replace(":00", "")
                binding.btnBloque.text = texto
            }
        }

        binding.btnPiso.setOnClickListener {
            mostrarDialogoSelector("Seleccionar Piso", opcionesPiso, pisoPos) { pos, texto ->
                pisoPos = pos
                pisoNumInt = pos + 1
                binding.btnPiso.text = texto
            }
        }

        binding.btnMetodoPago.setOnClickListener {
            mostrarDialogoSelector("Método de Pago", opcionesMetodo, metodoPos) { pos, texto ->
                metodoPos = pos
                metodoPagoStr = texto.lowercase()
                binding.btnMetodoPago.text = texto
            }
        }

        binding.btnTematica.setOnClickListener {
            val nombres = listaTematicas.map { it.nombre }
            mostrarDialogoSelector("Temática", nombres, tematicaPos) { pos, texto ->
                tematicaPos = pos
                tematicaSeleccionadaId = listaTematicas[pos].id
                binding.btnTematica.text = texto
            }
        }

        // --- Botón Volver ---
        binding.btnVolverReserva.setOnClickListener { finish() }

        // --- Botón Reservar: Validar y enviar ---
        binding.btnReservar.setOnClickListener {
            val personas = binding.etPersonas.text.toString().trim().toIntOrNull() ?: 0

            // Validaciones estrictas de todos los campos
            if (!validarFormularioReserva(personas)) return@setOnClickListener

            // Construir el body del request
            val body = ReservaRequest(
                cliente = ClienteReserva(
                    doc = cliCedula,
                    nom = cliNombre,
                    correo = cliCorreo,
                    tel = cliTelefono
                ),
                reserva = DatosReserva(
                    fec = fechaSeleccionada,
                    hor = bloqueHoraStr,
                    tematica = tematicaSeleccionadaId,
                    personas = personas,
                    piso = pisoNumInt,
                    metodoPago = metodoPagoStr
                ),
                pedido = if (carritoIdPlato != -1) listOf(
                    PedidoItem(
                        id = carritoIdPlato,
                        cantidad = carritoCantidad,
                        precio = carritoPrecio
                    )
                ) else emptyList()
            )

            // Si es transferencia, mostrar diálogo con datos bancarios
            if (metodoPagoStr == "transferencia") {
                val total = carritoPrecio * carritoCantidad
                mostrarDialogoTransferencia(total) {
                    viewModel.crearReserva(body)
                }
            } else {
                // Efectivo: enviar directo
                viewModel.crearReserva(body)
            }
        }
    }

    // ==================== VALIDACIONES ====================

    /**
     * Valida que todos los campos del formulario de reserva estén completos.
     * Muestra un Toast para el primer campo faltante.
     *
     * @return true si todo es válido, false si hay campos vacíos.
     */
    private fun validarFormularioReserva(personas: Int): Boolean {
        if (fechaSeleccionada.isEmpty()) {
            Toast.makeText(this, "Selecciona una fecha", Toast.LENGTH_SHORT).show()
            return false
        }
        if (bloqueHoraStr.isEmpty()) {
            Toast.makeText(this, "Selecciona un bloque horario", Toast.LENGTH_SHORT).show()
            return false
        }
        if (tematicaSeleccionadaId == -1) {
            Toast.makeText(this, "Selecciona una temática", Toast.LENGTH_SHORT).show()
            return false
        }
        if (personas <= 0) {
            Toast.makeText(this, "Ingresa el número de personas", Toast.LENGTH_SHORT).show()
            return false
        }
        if (personas > MAX_PERSONAS) {
            Toast.makeText(this, "Máximo $MAX_PERSONAS personas por reserva", Toast.LENGTH_SHORT).show()
            return false
        }
        if (pisoNumInt == -1) {
            Toast.makeText(this, "Selecciona un piso", Toast.LENGTH_SHORT).show()
            return false
        }
        if (metodoPagoStr.isEmpty()) {
            Toast.makeText(this, "Selecciona un método de pago", Toast.LENGTH_SHORT).show()
            return false
        }
        return true
    }

    // ==================== DIÁLOGO SELECTOR GENÉRICO ====================

    /**
     * Muestra un diálogo personalizado con una lista de opciones y selección visual.
     * Reutilizado por todos los selectores (bloque, piso, pago, temática).
     *
     * Principio DRY: Una sola función para todos los diálogos de selección.
     *
     * @param titulo Título del diálogo.
     * @param opciones Lista de textos a mostrar.
     * @param indiceActual Índice actualmente seleccionado (-1 si ninguno).
     * @param alSeleccionar Lambda que recibe el índice y texto seleccionados.
     */
    private fun mostrarDialogoSelector(
        titulo: String,
        opciones: List<String>,
        indiceActual: Int,
        alSeleccionar: (Int, String) -> Unit
    ) {
        val dialog = Dialog(this)
        dialog.requestWindowFeature(Window.FEATURE_NO_TITLE)
        dialog.setContentView(R.layout.dialog_selector_generico)
        dialog.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))

        dialog.findViewById<TextView>(R.id.tvTituloDialogo).text = titulo
        val contenedor = dialog.findViewById<LinearLayout>(R.id.contenedorOpciones)

        // Si no hay selección previa, elegir el primer elemento por defecto
        var indiceTemp = if (indiceActual == -1 && opciones.isNotEmpty()) 0 else indiceActual
        val vistasFilas = mutableListOf<View>()

        for (i in opciones.indices) {
            val vistaFila = LayoutInflater.from(this)
                .inflate(R.layout.item_opcion_dialogo, contenedor, false)
            val tvTexto  = vistaFila.findViewById<TextView>(R.id.tvTextoOpcion)
            val imgCheck = vistaFila.findViewById<ImageButton>(R.id.imgCheckOpcion)

            tvTexto.text = opciones[i]

            // Estilo visual de selección
            if (i == indiceTemp) {
                imgCheck.setImageResource(R.drawable.ic_radio_seleccionado)
                tvTexto.setTextColor(Color.parseColor("#FFFFFF"))
            } else {
                imgCheck.setImageResource(R.drawable.ic_radio_vacio)
                tvTexto.setTextColor(Color.parseColor("#99FFFFFF"))
            }

            vistaFila.setOnClickListener {
                indiceTemp = i
                vistasFilas.forEachIndexed { index, vista ->
                    val img = vista.findViewById<ImageButton>(R.id.imgCheckOpcion)
                    val txt = vista.findViewById<TextView>(R.id.tvTextoOpcion)

                    if (index == indiceTemp) {
                        img.setImageResource(R.drawable.ic_radio_seleccionado)
                        txt.setTextColor(Color.parseColor("#FFFFFF"))
                    } else {
                        img.setImageResource(R.drawable.ic_radio_vacio)
                        txt.setTextColor(Color.parseColor("#99FFFFFF"))
                    }
                }
            }

            contenedor.addView(vistaFila)
            vistasFilas.add(vistaFila)
        }

        dialog.findViewById<Button>(R.id.btnCancelarDialogo).setOnClickListener { dialog.dismiss() }
        dialog.findViewById<Button>(R.id.btnAceptarDialogo).setOnClickListener {
            if (indiceTemp != -1) alSeleccionar(indiceTemp, opciones[indiceTemp])
            dialog.dismiss()
        }
        dialog.show()
    }

    // ==================== DIÁLOGO TRANSFERENCIA ====================

    /**
     * Muestra un diálogo personalizado con los datos bancarios para
     * realizar la transferencia, similar a la versión web.
     *
     * Incluye: datos de cuenta, advertencia, total, zona para adjuntar
     * comprobante y botón de envío.
     *
     * @param total Monto total a pagar.
     * @param alConfirmar Lambda que se ejecuta cuando el usuario confirma el envío.
     */
    private fun mostrarDialogoTransferencia(total: Double, alConfirmar: () -> Unit) {
        comprobanteUri = null // Resetear comprobante anterior

        val dialog = Dialog(this)
        dialog.requestWindowFeature(Window.FEATURE_NO_TITLE)
        dialog.setContentView(R.layout.dialog_transferencia)
        dialog.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
        dialogTransferenciaActivo = dialog

        // Formatear el total con separador de miles
        val formato = NumberFormat.getNumberInstance(Locale("es", "CO"))
        formato.maximumFractionDigits = 0
        val totalFormateado = formato.format(total)

        dialog.findViewById<TextView>(R.id.tvTotalPagar).text = "TOTAL A PAGAR: $ $totalFormateado"

        // Zona para seleccionar comprobante
        dialog.findViewById<LinearLayout>(R.id.layoutSeleccionarComprobante).setOnClickListener {
            selectorComprobante.launch("image/*")
        }

        // Botón enviar comprobante → confirmar pedido
        dialog.findViewById<Button>(R.id.btnEnviarComprobante).setOnClickListener {
            if (comprobanteUri == null) {
                Toast.makeText(this, "Selecciona un comprobante de pago", Toast.LENGTH_SHORT).show()
                return@setOnClickListener
            }
            dialog.dismiss()
            dialogTransferenciaActivo = null
            alConfirmar()
        }

        // Botón cancelar
        dialog.findViewById<Button>(R.id.btnCancelarTransferencia).setOnClickListener {
            dialog.dismiss()
            dialogTransferenciaActivo = null
        }

        dialog.setOnDismissListener { dialogTransferenciaActivo = null }
        dialog.show()
    }

    /**
     * Obtiene el nombre del archivo desde una URI de contenido.
     * Intenta extraer del cursor; si no, usa el último segmento de la URI.
     */
    private fun obtenerNombreArchivo(uri: Uri): String {
        var nombre = "Comprobante seleccionado"
        contentResolver.query(uri, null, null, null, null)?.use { cursor ->
            val index = cursor.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
            if (index != -1 && cursor.moveToFirst()) {
                nombre = cursor.getString(index)
            }
        }
        return nombre
    }

    companion object {
        /** Número máximo de personas permitido por reserva. */
        private const val MAX_PERSONAS = 10
    }
}

package com.sena.myapplication.views

import android.app.DatePickerDialog
import android.app.Dialog
import android.content.Intent
import android.graphics.Color
import android.graphics.drawable.ColorDrawable
import android.net.Uri
import android.os.Bundle
import android.view.LayoutInflater
import android.view.View
import android.view.Window
import android.widget.Button
import android.widget.ImageButton
import android.widget.LinearLayout
import android.widget.TextView
import android.widget.Toast
import androidx.activity.result.contract.ActivityResultContracts
import androidx.lifecycle.ViewModelProvider
import com.sena.myapplication.R
import com.sena.myapplication.databinding.ActivityReservaBinding
import com.sena.myapplication.models.*
import com.sena.myapplication.viewmodels.ViewModelReserva
import java.text.NumberFormat
import java.util.Calendar
import java.util.Locale

/**
 * Pantalla de reserva — El usuario selecciona fecha, hora, temática,
 * piso, método de pago y número de personas.
 *
 * Patrón MVVM: Toda la lógica de red (cargar temáticas, enviar reserva)
 * se delega a [ViewModelReserva]. La Activity solo gestiona la UI.
 *
 * Recibe datos del cliente (CLI_*) y del carrito (CARRITO_*) para
 * construir el [ReservaRequest] completo.
 */
class ReservaActivity : BaseActivity() {

    private lateinit var binding: ActivityReservaBinding
    private lateinit var viewModel: ViewModelReserva

    // Estado de selección de la reserva
    private var listaTematicas: List<ModelTematica> = emptyList()
    private var fechaSeleccionada = ""
    private var bloqueHoraStr = ""
    private var bloquePos = -1
    private var tematicaSeleccionadaId = -1
    private var tematicaPos = -1
    private var pisoNumInt = -1
    private var pisoPos = -1
    private var metodoPagoStr = ""
    private var metodoPos = -1

    // Estado para el comprobante de transferencia
    private var comprobanteUri: Uri? = null
    private var dialogTransferenciaActivo: Dialog? = null

    /** Launcher para seleccionar imagen del comprobante desde la galería */
    private val selectorComprobante = registerForActivityResult(
        ActivityResultContracts.GetContent()
    ) { uri: Uri? ->
        uri?.let {
            comprobanteUri = it
            // Actualizar texto en el diálogo activo
            dialogTransferenciaActivo?.findViewById<TextView>(R.id.tvNombreArchivo)?.text =
                obtenerNombreArchivo(it)
        }
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        binding = ActivityReservaBinding.inflate(layoutInflater)
        setContentView(binding.root)
        configurarBarraNavegacion()

        // --- Recibir datos del Intent ---
        val cliNombre   = intent.getStringExtra("CLI_NOMBRE") ?: ""
        val cliCedula   = intent.getStringExtra("CLI_CEDULA") ?: ""
        val cliCorreo   = intent.getStringExtra("CLI_CORREO") ?: ""
        val cliTelefono = intent.getStringExtra("CLI_TELEFONO") ?: ""

        val carritoIdPlato  = intent.getIntExtra("CARRITO_ID_PLATO", -1)
        val carritoCantidad = intent.getIntExtra("CARRITO_CANTIDAD", 1)
        val carritoPrecio   = intent.getDoubleExtra("CARRITO_PRECIO_UNITARIO", 0.0)

        // --- Opciones de selección ---
        val opcionesBloque = (6..22).map { "$it:00" }
        val opcionesPiso   = listOf("Piso 1", "Piso 2")
        val opcionesMetodo = listOf("Efectivo", "Transferencia")

        // --- Inicializar ViewModel ---
        viewModel = ViewModelProvider(this)[ViewModelReserva::class.java]

        // Observar temáticas cargadas
        viewModel.tematicas.observe(this) { tematicas ->
            listaTematicas = tematicas
            binding.btnTematica.text = "Seleccionar Temática"
            binding.btnTematica.isEnabled = true
        }

        // Observar resultado de crear reserva → navegar a confirmación
        viewModel.reservaExitosa.observe(this) { response ->
            response?.let {
                val intent = Intent(this, ConfirmacionReservaActivity::class.java)
                intent.putExtra("QR_BASE64", it.qr ?: "")
                startActivity(intent)
                finishAffinity()
            }
        }

        // Observar errores de red
        viewModel.error.observe(this) { mensajeError ->
            mensajeError?.let {
                Toast.makeText(this, it, Toast.LENGTH_LONG).show()
            }
        }

        // Observar estado de envío para habilitar/deshabilitar botón
        viewModel.enviando.observe(this) { enviando ->
            binding.btnReservar.isEnabled = !enviando
            binding.btnReservar.text = if (enviando) "Enviando..." else "RESERVAR"
        }

        // Disparar carga de temáticas
        viewModel.cargarTematicas()

        // --- Listeners de selección ---

        binding.btnFecha.setOnClickListener {
            val manana = Calendar.getInstance()
            manana.add(Calendar.DAY_OF_YEAR, 1)

            val picker = DatePickerDialog(
                this, R.style.CalendarioPersonalizado, { _, y, m, d ->
                    val mes = String.format("%02d", m + 1)
                    val dia = String.format("%02d", d)
                    fechaSeleccionada = "$y-$mes-$dia"
                    binding.btnFecha.text = fechaSeleccionada
                }, manana.get(Calendar.YEAR), manana.get(Calendar.MONTH), manana.get(Calendar.DAY_OF_MONTH)
            )
            picker.datePicker.minDate = manana.timeInMillis
            picker.show()
        }

        binding.btnBloque.setOnClickListener {
            mostrarDialogoSelector("Bloque Horario", opcionesBloque, bloquePos) { pos, texto ->
                bloquePos = pos
                bloqueHoraStr = texto.replace(":00", "")
                binding.btnBloque.text = texto
            }
        }

        binding.btnPiso.setOnClickListener {
            mostrarDialogoSelector("Seleccionar Piso", opcionesPiso, pisoPos) { pos, texto ->
                pisoPos = pos
                pisoNumInt = pos + 1
                binding.btnPiso.text = texto
            }
        }

        binding.btnMetodoPago.setOnClickListener {
            mostrarDialogoSelector("Método de Pago", opcionesMetodo, metodoPos) { pos, texto ->
                metodoPos = pos
                metodoPagoStr = texto.lowercase()
                binding.btnMetodoPago.text = texto
            }
        }

        binding.btnTematica.setOnClickListener {
            val nombres = listaTematicas.map { it.nombre }
            mostrarDialogoSelector("Temática", nombres, tematicaPos) { pos, texto ->
                tematicaPos = pos
                tematicaSeleccionadaId = listaTematicas[pos].id
                binding.btnTematica.text = texto
            }
        }

        // --- Botón Volver ---
        binding.btnVolverReserva.setOnClickListener { finish() }

        // --- Botón Reservar: Validar y enviar ---
        binding.btnReservar.setOnClickListener {
            val personas = binding.etPersonas.text.toString().trim().toIntOrNull() ?: 0

            // Validaciones estrictas de todos los campos
            if (!validarFormularioReserva(personas)) return@setOnClickListener

            // Construir el body del request
            val body = ReservaRequest(
                cliente = ClienteReserva(
                    doc = cliCedula,
                    nom = cliNombre,
                    correo = cliCorreo,
                    tel = cliTelefono
                ),
                reserva = DatosReserva(
                    fec = fechaSeleccionada,
                    hor = bloqueHoraStr,
                    tematica = tematicaSeleccionadaId,
                    personas = personas,
                    piso = pisoNumInt,
                    metodoPago = metodoPagoStr
                ),
                pedido = if (carritoIdPlato != -1) listOf(
                    PedidoItem(
                        id = carritoIdPlato,
                        cantidad = carritoCantidad,
                        precio = carritoPrecio
                    )
                ) else emptyList()
            )

            // Si es transferencia, mostrar diálogo con datos bancarios
            if (metodoPagoStr == "transferencia") {
                val total = carritoPrecio * carritoCantidad
                mostrarDialogoTransferencia(total) {
                    viewModel.crearReserva(body)
                }
            } else {
                // Efectivo: enviar directo
                viewModel.crearReserva(body)
            }
        }
    }

    // ==================== VALIDACIONES ====================

    /**
     * Valida que todos los campos del formulario de reserva estén completos.
     * Muestra un Toast para el primer campo faltante.
     *
     * @return true si todo es válido, false si hay campos vacíos.
     */
    private fun validarFormularioReserva(personas: Int): Boolean {
        if (fechaSeleccionada.isEmpty()) {
            Toast.makeText(this, "Selecciona una fecha", Toast.LENGTH_SHORT).show()
            return false
        }
        if (bloqueHoraStr.isEmpty()) {
            Toast.makeText(this, "Selecciona un bloque horario", Toast.LENGTH_SHORT).show()
            return false
        }
        if (tematicaSeleccionadaId == -1) {
            Toast.makeText(this, "Selecciona una temática", Toast.LENGTH_SHORT).show()
            return false
        }
        if (personas <= 0) {
            Toast.makeText(this, "Ingresa el número de personas", Toast.LENGTH_SHORT).show()
            return false
        }
        if (personas > MAX_PERSONAS) {
            Toast.makeText(this, "Máximo $MAX_PERSONAS personas por reserva", Toast.LENGTH_SHORT).show()
            return false
        }
        if (pisoNumInt == -1) {
            Toast.makeText(this, "Selecciona un piso", Toast.LENGTH_SHORT).show()
            return false
        }
        if (metodoPagoStr.isEmpty()) {
            Toast.makeText(this, "Selecciona un método de pago", Toast.LENGTH_SHORT).show()
            return false
        }
        return true
    }

    // ==================== DIÁLOGO SELECTOR GENÉRICO ====================

    /**
     * Muestra un diálogo personalizado con una lista de opciones y selección visual.
     * Reutilizado por todos los selectores (bloque, piso, pago, temática).
     *
     * Principio DRY: Una sola función para todos los diálogos de selección.
     *
     * @param titulo Título del diálogo.
     * @param opciones Lista de textos a mostrar.
     * @param indiceActual Índice actualmente seleccionado (-1 si ninguno).
     * @param alSeleccionar Lambda que recibe el índice y texto seleccionados.
     */
    private fun mostrarDialogoSelector(
        titulo: String,
        opciones: List<String>,
        indiceActual: Int,
        alSeleccionar: (Int, String) -> Unit
    ) {
        val dialog = Dialog(this)
        dialog.requestWindowFeature(Window.FEATURE_NO_TITLE)
        dialog.setContentView(R.layout.dialog_selector_generico)
        dialog.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))

        dialog.findViewById<TextView>(R.id.tvTituloDialogo).text = titulo
        val contenedor = dialog.findViewById<LinearLayout>(R.id.contenedorOpciones)

        // Si no hay selección previa, elegir el primer elemento por defecto
        var indiceTemp = if (indiceActual == -1 && opciones.isNotEmpty()) 0 else indiceActual
        val vistasFilas = mutableListOf<View>()

        for (i in opciones.indices) {
            val vistaFila = LayoutInflater.from(this)
                .inflate(R.layout.item_opcion_dialogo, contenedor, false)
            val tvTexto  = vistaFila.findViewById<TextView>(R.id.tvTextoOpcion)
            val imgCheck = vistaFila.findViewById<ImageButton>(R.id.imgCheckOpcion)

            tvTexto.text = opciones[i]

            // Estilo visual de selección
            if (i == indiceTemp) {
                imgCheck.setImageResource(R.drawable.ic_radio_seleccionado)
                tvTexto.setTextColor(Color.parseColor("#FFFFFF"))
            } else {
                imgCheck.setImageResource(R.drawable.ic_radio_vacio)
                tvTexto.setTextColor(Color.parseColor("#99FFFFFF"))
            }

            vistaFila.setOnClickListener {
                indiceTemp = i
                vistasFilas.forEachIndexed { index, vista ->
                    val img = vista.findViewById<ImageButton>(R.id.imgCheckOpcion)
                    val txt = vista.findViewById<TextView>(R.id.tvTextoOpcion)

                    if (index == indiceTemp) {
                        img.setImageResource(R.drawable.ic_radio_seleccionado)
                        txt.setTextColor(Color.parseColor("#FFFFFF"))
                    } else {
                        img.setImageResource(R.drawable.ic_radio_vacio)
                        txt.setTextColor(Color.parseColor("#99FFFFFF"))
                    }
                }
            }

            contenedor.addView(vistaFila)
            vistasFilas.add(vistaFila)
        }

        dialog.findViewById<Button>(R.id.btnCancelarDialogo).setOnClickListener { dialog.dismiss() }
        dialog.findViewById<Button>(R.id.btnAceptarDialogo).setOnClickListener {
            if (indiceTemp != -1) alSeleccionar(indiceTemp, opciones[indiceTemp])
            dialog.dismiss()
        }
        dialog.show()
    }

    // ==================== DIÁLOGO TRANSFERENCIA ====================

    /**
     * Muestra un diálogo personalizado con los datos bancarios para
     * realizar la transferencia, similar a la versión web.
     *
     * Incluye: datos de cuenta, advertencia, total, zona para adjuntar
     * comprobante y botón de envío.
     *
     * @param total Monto total a pagar.
     * @param alConfirmar Lambda que se ejecuta cuando el usuario confirma el envío.
     */
    private fun mostrarDialogoTransferencia(total: Double, alConfirmar: () -> Unit) {
        comprobanteUri = null // Resetear comprobante anterior

        val dialog = Dialog(this)
        dialog.requestWindowFeature(Window.FEATURE_NO_TITLE)
        dialog.setContentView(R.layout.dialog_transferencia)
        dialog.window?.setBackgroundDrawable(ColorDrawable(Color.TRANSPARENT))
        dialog.window?.setDimAmount(0.85f)
        dialogTransferenciaActivo = dialog

        // Formatear el total con separador de miles
        val formato = NumberFormat.getNumberInstance(Locale("es", "CO"))
        formato.maximumFractionDigits = 0
        val totalFormateado = formato.format(total)

        dialog.findViewById<TextView>(R.id.tvTotalPagar).text = "TOTAL A PAGAR: $ $totalFormateado"

        // Zona para seleccionar comprobante
        dialog.findViewById<LinearLayout>(R.id.layoutSeleccionarComprobante).setOnClickListener {
            selectorComprobante.launch("image/*")
        }

        // Botón enviar comprobante → confirmar pedido
        dialog.findViewById<Button>(R.id.btnEnviarComprobante).setOnClickListener {
            if (comprobanteUri == null) {
                Toast.makeText(this, "Selecciona un comprobante de pago", Toast.LENGTH_SHORT).show()
                return@setOnClickListener
            }
            dialog.dismiss()
            dialogTransferenciaActivo = null
            alConfirmar()
        }

        // Botón cancelar
        dialog.findViewById<Button>(R.id.btnCancelarTransferencia).setOnClickListener {
            dialog.dismiss()
            dialogTransferenciaActivo = null
        }

        dialog.setOnDismissListener { dialogTransferenciaActivo = null }
        dialog.show()
    }

    /**
     * Obtiene el nombre del archivo desde una URI de contenido.
     * Intenta extraer del cursor; si no, usa el último segmento de la URI.
     */
    private fun obtenerNombreArchivo(uri: Uri): String {
        var nombre = "Comprobante seleccionado"
        contentResolver.query(uri, null, null, null, null)?.use { cursor ->
            val index = cursor.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME)
            if (index != -1 && cursor.moveToFirst()) {
                nombre = cursor.getString(index)
            }
        }
        return nombre
    }

    companion object {
        /** Número máximo de personas permitido por reserva. */
        private const val MAX_PERSONAS = 10
    }
}

package com.sena.myapplication.views

import android.content.Intent
import android.os.Bundle
import android.widget.Toast
import androidx.lifecycle.ViewModelProvider
import androidx.recyclerview.widget.LinearLayoutManager
import com.sena.myapplication.adapters.AdapterPlato
import com.sena.myapplication.databinding.ActivityVerPlatosBinding
import com.sena.myapplication.models.ModelPlato
import com.sena.myapplication.viewmodels.ViewModelPlato

/**
 * Pantalla de platos por categoría — Lista los platos disponibles.
 *
 * El usuario selecciona un plato para ver sus detalles (tamaño, sabor, adiciones).
 * Recibe ID_CATEGORIA y NOMBRE_CATEGORIA como extras del Intent.
 */
class VerPlatosActivity : BaseActivity() {

    private lateinit var binding: ActivityVerPlatosBinding
    private lateinit var viewModel: ViewModelPlato
    private lateinit var adapter: AdapterPlato

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        binding = ActivityVerPlatosBinding.inflate(layoutInflater)
        setContentView(binding.root)
        configurarBarraNavegacion()

        // Configurar RecyclerView con layout lineal
        binding.recyclerViewPlatos.layoutManager = LinearLayoutManager(this)
        adapter = AdapterPlato(emptyList()) { abrirDetalle(it) }
        binding.recyclerViewPlatos.adapter = adapter

        // Recibir extras del Intent
        val idCategoria     = intent.getIntExtra("ID_CATEGORIA", -1)
        val nombreCategoria = intent.getStringExtra("NOMBRE_CATEGORIA")
        binding.tvCategoriaNombre.text = nombreCategoria ?: ""

        // Inicializar ViewModel y observar datos
        viewModel = ViewModelProvider(this)[ViewModelPlato::class.java]

        viewModel.platos.observe(this) { platos ->
            adapter.actualizarLista(platos)
        }

        viewModel.error.observe(this) { mensajeError ->
            mensajeError?.let {
                Toast.makeText(this, it, Toast.LENGTH_SHORT).show()
            }
        }

        // Validar que se recibió la categoría y disparar carga
        if (idCategoria != -1) {
            viewModel.obtenerPlatosPorCategoria(idCategoria)
        } else {
            Toast.makeText(this, "Error: No se recibió la categoría", Toast.LENGTH_SHORT).show()
        }
    }

    /**
     * Navega al detalle del plato seleccionado.
     * Pasa los datos básicos del plato como extras del Intent.
     */
    private fun abrirDetalle(plato: ModelPlato) {
        val intent = Intent(this, PlatoDetalleActivity::class.java).apply {
            putExtra("ID_PLATO",          plato.id)
            putExtra("NOMBRE_PLATO",      plato.nombre)
            putExtra("DESCRIPCION_PLATO", plato.descripcion)
            putExtra("IMAGEN_PLATO",      plato.imagen)
            putExtra("PRECIO_PLATO",      plato.precio)
        }
        startActivity(intent)
    }
}

package com.sena.myapplication.views

import android.content.Intent
import android.os.Bundle
import android.widget.Toast
import androidx.lifecycle.ViewModelProvider
import androidx.recyclerview.widget.LinearLayoutManager
import com.sena.myapplication.adapters.AdapterPlato
import com.sena.myapplication.databinding.ActivityVerPlatosBinding
import com.sena.myapplication.models.ModelPlato
import com.sena.myapplication.viewmodels.ViewModelPlato

/**
 * Pantalla de platos por categoría — Lista los platos disponibles.
 *
 * Principio SRP: Solo gestiona la UI de listado de platos.
 * La carga de datos se delega a [ViewModelPlato].
 *
 * Principio DIP: Depende de la abstracción [ViewModelPlato],
 * no de llamadas Retrofit directas.
 *
 * Principio OCP: Hereda la barra de navegación de [BaseActivity].
 *
 * El usuario selecciona un plato para ver sus detalles (tamaño, sabor, adiciones).
 * Recibe ID_CATEGORIA y NOMBRE_CATEGORIA como extras del Intent.
 */
class VerPlatosActivity : BaseActivity() {

    private lateinit var binding: ActivityVerPlatosBinding
    private lateinit var viewModel: ViewModelPlato
    private lateinit var adapter: AdapterPlato

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)

        binding = ActivityVerPlatosBinding.inflate(layoutInflater)
        setContentView(binding.root)
        configurarBarraNavegacion()

        // Configurar RecyclerView con layout lineal
        binding.recyclerViewPlatos.layoutManager = LinearLayoutManager(this)
        adapter = AdapterPlato(emptyList()) { abrirDetalle(it) }
        binding.recyclerViewPlatos.adapter = adapter

        // Recibir extras del Intent
        val idCategoria     = intent.getIntExtra("ID_CATEGORIA", -1)
        val nombreCategoria = intent.getStringExtra("NOMBRE_CATEGORIA")
        binding.tvCategoriaNombre.text = nombreCategoria ?: ""

        // Inicializar ViewModel y observar datos
        viewModel = ViewModelProvider(this)[ViewModelPlato::class.java]

        viewModel.platos.observe(this) { platos ->
            adapter.actualizarLista(platos)
        }

        viewModel.error.observe(this) { mensajeError ->
            mensajeError?.let {
                Toast.makeText(this, it, Toast.LENGTH_SHORT).show()
            }
        }

        // Validar que se recibió la categoría y disparar carga
        if (idCategoria != -1) {
            viewModel.obtenerPlatosPorCategoria(idCategoria)
        } else {
            Toast.makeText(this, "Error: No se recibió la categoría", Toast.LENGTH_SHORT).show()
        }
    }

    /**
     * Navega al detalle del plato seleccionado.
     * Pasa los datos básicos del plato como extras del Intent.
     */
    private fun abrirDetalle(plato: ModelPlato) {
        val intent = Intent(this, PlatoDetalleActivity::class.java).apply {
            putExtra("ID_PLATO",          plato.id)
            putExtra("NOMBRE_PLATO",      plato.nombre)
            putExtra("DESCRIPCION_PLATO", plato.descripcion)
            putExtra("IMAGEN_PLATO",      plato.imagen)
            putExtra("PRECIO_PLATO",      plato.precio)
        }
        startActivity(intent)
    }
}

package com.sena.myapplication.viewmodels

import android.util.Log
import androidx.lifecycle.LiveData
import androidx.lifecycle.MutableLiveData
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import com.sena.myapplication.models.ActualizarReservaRequest
import com.sena.myapplication.models.ModelMiReserva
import com.sena.myapplication.models.ReservaResponse
import com.sena.myapplication.services.ConexionServiceReserva
import kotlinx.coroutines.launch

/**
 * ViewModel para la pantalla "Mis Reservas" (MisReservasActivity).
 *
 * Gestiona: buscar reservas por cédula, actualizar y eliminar.
 *
 * Principio SRP: Encapsula toda la lógica de red de consulta/edición/eliminación
 * de reservas, dejando la Activity enfocada solo en la UI.
 *
 * Principio DIP (Dependency Inversion): Depende de la interfaz
 * [ConexionServiceReserva] y no de una implementación concreta de Retrofit.
 *
 * Usa coroutines con [viewModelScope] para llamadas asíncronas.
 * Implementa reintento automático (máx. 2) ante fallos de red.
 */
class ViewModelMisReservas : ViewModel() {

    private val api = ConexionServiceReserva.instance

    // --- Resultado de búsqueda ---
    private val _reservas = MutableLiveData<List<ModelMiReserva>>()
    val reservas: LiveData<List<ModelMiReserva>> get() = _reservas

    // --- Resultado de actualización ---
    private val _actualizacionExitosa = MutableLiveData<ReservaResponse?>()
    val actualizacionExitosa: LiveData<ReservaResponse?> get() = _actualizacionExitosa

    // --- Resultado de eliminación ---
    private val _eliminacionExitosa = MutableLiveData<ReservaResponse?>()
    val eliminacionExitosa: LiveData<ReservaResponse?> get() = _eliminacionExitosa

    // --- Estados de UI ---
    private val _error = MutableLiveData<String?>()
    val error: LiveData<String?> get() = _error

    private val _cargando = MutableLiveData<Boolean>()
    val cargando: LiveData<Boolean> get() = _cargando

    // ------------------------------------------------------------------
    // Buscar reservas por cédula
    // ------------------------------------------------------------------

    fun buscarPorCedula(cedula: String) {
        _cargando.value = true
        _error.value = null
        buscarConReintento(cedula, intentos = 0)
    }

    private fun buscarConReintento(cedula: String, intentos: Int) {
        viewModelScope.launch {
            try {
                val response = api.buscarReservasPorCedula(cedula)
                _cargando.value = false

                if (response.isSuccessful && response.body() != null) {
                    val lista = response.body()!!
                    _reservas.value = lista
                    if (lista.isEmpty()) {
                        _error.value = "No se encontraron reservas para esta cédula"
                    }
                    Log.d(TAG, "Reservas encontradas: ${lista.size}")
                } else {
                    // Leer cuerpo de error para diagnóstico
                    val errorBody = try { response.errorBody()?.string() } catch (_: Exception) { null }
                    Log.e(TAG, "Error HTTP ${response.code()}: $errorBody")

                    _reservas.value = emptyList()
                    _error.value = when (response.code()) {
                        404 -> "Ruta no encontrada en el servidor (404). Verifica que el microservicio tenga la ruta GET /api/reservas/<cedula>"
                        500 -> "Error interno del servidor (500): ${errorBody ?: "sin detalles"}"
                        else -> "Error del servidor (código ${response.code()})"
                    }
                }
            } catch (e: Exception) {
                Log.e(TAG, "Error buscando reservas (intento $intentos): ${e.message}", e)
                if (intentos < MAX_REINTENTOS) {
                    buscarConReintento(cedula, intentos + 1)
                    return@launch
                }
                _cargando.value = false
                _reservas.value = emptyList()
                _error.value = "Error de conexión: ${e.message}"
            }
        }
    }

    // ------------------------------------------------------------------
    // Actualizar reserva
    // ------------------------------------------------------------------

    fun actualizarReserva(reservaId: Int, body: ActualizarReservaRequest) {
        _cargando.value = true
        _error.value = null
        actualizarConReintento(reservaId, body, intentos = 0)
    }

    private fun actualizarConReintento(reservaId: Int, body: ActualizarReservaRequest, intentos: Int) {
        viewModelScope.launch {
            try {
                val response = api.actualizarReserva(reservaId, body)
                _cargando.value = false

                if (response.isSuccessful) {
                    _actualizacionExitosa.value = response.body()
                    Log.d(TAG, "Reserva $reservaId actualizada")
                } else {
                    val errorBody = try { response.errorBody()?.string() } catch (_: Exception) { null }
                    Log.e(TAG, "Error actualizando HTTP ${response.code()}: $errorBody")
                    _error.value = when (response.code()) {
                        404 -> "Ruta PUT no encontrada en el servidor (404)"
                        500 -> "Error interno del servidor al actualizar"
                        else -> "Error al actualizar (código ${response.code()})"
                    }
                }
            } catch (e: Exception) {
                Log.e(TAG, "Error actualizando (intento $intentos): ${e.message}", e)
                if (intentos < MAX_REINTENTOS) {
                    actualizarConReintento(reservaId, body, intentos + 1)
                    return@launch
                }
                _cargando.value = false
                _error.value = "Error de red: ${e.message}"
            }
        }
    }

    // ------------------------------------------------------------------
    // Eliminar reserva
    // ------------------------------------------------------------------

    fun eliminarReserva(reservaId: Int) {
        _cargando.value = true
        _error.value = null
        eliminarConReintento(reservaId, intentos = 0)
    }

    private fun eliminarConReintento(reservaId: Int, intentos: Int) {
        viewModelScope.launch {
            try {
                val response = api.eliminarReserva(reservaId)
                _cargando.value = false

                if (response.isSuccessful) {
                    _eliminacionExitosa.value = response.body()
                    Log.d(TAG, "Reserva $reservaId eliminada")
                } else {
                    val msg = response.body()?.message ?: "Error al eliminar (código ${response.code()})"
                    _error.value = msg
                }
            } catch (e: Exception) {
                Log.e(TAG, "Error eliminando (intento $intentos): ${e.message}")
                if (intentos < MAX_REINTENTOS) {
                    eliminarConReintento(reservaId, intentos + 1)
                    return@launch
                }
                _cargando.value = false
                _error.value = "Error de red: ${e.message}"
            }
        }
    }

    companion object {
        private const val TAG = "VMMisReservas"
        private const val MAX_REINTENTOS = 2
    }
}

